-- Igual que measure-search.sql, pero con la consulta reescrita como UNION de tres ramas (variante B).
-- Correr con los índices temporales creados. 3 corridas por palabra; mirar la 3ª.
\timing on

\echo === catering
SELECT 'catering' AS palabra, count(*) AS total FROM (SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."DisplayName", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."Description", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p JOIN "ProviderOfferings" po ON po."ProviderId" = p."Id" JOIN "Offerings" o ON o."Id" = po."OfferingId" WHERE p."Status" = 'Published' AND f_matches(o."Name", lower('%catering%'))) t;
SELECT 'catering' AS palabra, count(*) AS total FROM (SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."DisplayName", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."Description", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p JOIN "ProviderOfferings" po ON po."ProviderId" = p."Id" JOIN "Offerings" o ON o."Id" = po."OfferingId" WHERE p."Status" = 'Published' AND f_matches(o."Name", lower('%catering%'))) t;
SELECT 'catering' AS palabra, count(*) AS total FROM (SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."DisplayName", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p WHERE p."Status" = 'Published' AND f_matches(p."Description", lower('%catering%')) UNION SELECT p."Id" FROM "Providers" p JOIN "ProviderOfferings" po ON po."ProviderId" = p."Id" JOIN "Offerings" o ON o."Id" = po."OfferingId" WHERE p."Status" = 'Published' AND f_matches(o."Name", lower('%catering%'))) t;

